[metadata] {"type": "create", "filePath": "/workspace/repo/crates/hstr/src/lib.rs", "content": "//! `hstr` provides [`Atom`], an immutable, reference-counted string type which
//! is optimized for fast hashing and comparison, along with [`AtomStore`],
//! which interns strings into [`Atom`]s.
//!
//! Interning strings through the same [`AtomStore`] guarantees that two atoms
//! representing the same text share the same backing allocation, so equality
//! checks become a pointer comparison. Atoms created from different stores still
//! compare equal (by content) and hash identically, but they do not share the
//! same allocation.

use std::{
    borrow::Cow,
    collections::HashMap,
    fmt,
    hash::{Hash, Hasher},
    sync::Arc,
};

/// The heap-allocated payload backing an [`Atom`].
///
/// The hash is computed once, at interning time, using a deterministic hasher
/// so that atoms representing the same string hash identically regardless of
/// which [`AtomStore`] created them.
struct Entry {
    string: Box<str>,
    hash: u64,
}

/// The internal representation of an [`Atom`].
///
/// It keeps the backing [`Entry`] alive through an [`Arc`], which is why an
/// [`Atom`] stays valid even after the [`AtomStore`] that created it is dropped.
///
/// Equality of `TaggedValue` is *identity* (pointer) based: two values are
/// equal only when they point at the very same allocation. This is what makes
/// atoms interned by the same store share an equal `unsafe_data`, while atoms
/// from different stores (even for the same text) do not.
#[derive(Clone)]
struct TaggedValue {
    entry: Arc<Entry>,
}

impl PartialEq for TaggedValue {
    #[inline]
    fn eq(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.entry, &other.entry)
    }
}

impl Eq for TaggedValue {}

/// An immutable string type optimized for fast hashing and comparison.
///
/// Atoms are cheap to clone (an atomic reference-count bump) and cheap to
/// compare when they originate from the same [`AtomStore`] (a pointer
/// comparison). Atoms remain valid and usable after their originating store is
/// dropped.
#[derive(Clone)]
pub struct Atom {
    unsafe_data: TaggedValue,
}

impl Atom {
    #[inline]
    fn new(string: Box<str>, hash: u64) -> Self {
        Atom {
            unsafe_data: TaggedValue {
                entry: Arc::new(Entry { string, hash }),
            },
        }
    }

    /// The string value of this atom.
    #[inline]
    pub fn as_str(&self) -> &str {
        &self.unsafe_data.entry.string
    }

    /// Returns a stable hash of the underlying string.
    ///
    /// The value is consistent for atoms representing the same string, no matter
    /// which [`AtomStore`] created them.
    #[inline]
    fn get_hash(&self) -> u64 {
        self.unsafe_data.entry.hash
    }
}

impl PartialEq for Atom {
    #[inline]
    fn eq(&self, other: &Self) -> bool {
        // Fast path: atoms interned by the same store share an allocation.
        if self.unsafe_data == other.unsafe_data {
            return true;
        }

        // Slow path: atoms from different stores are compared by hash and then
        // by content, so that identical text always compares equal.
        self.get_hash() == other.get_hash() && self.as_str() == other.as_str()
    }
}

impl Eq for Atom {}

impl Hash for Atom {
    #[inline]
    fn hash<H: Hasher>(&self, state: &mut H) {
        state.write_u64(self.get_hash());
    }
}

impl fmt::Debug for Atom {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Debug::fmt(self.as_str(), f)
    }
}

impl fmt::Display for Atom {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(self.as_str(), f)
    }
}

impl std::ops::Deref for Atom {
    type Target = str;

    #[inline]
    fn deref(&self) -> &str {
        self.as_str()
    }
}

/// Computes a deterministic hash of `text`.
///
/// [`std::collections::hash_map::DefaultHasher`] uses fixed keys, so the hash is
/// stable for a given input within a build and is independent of any particular
/// [`AtomStore`].
fn hash_str(text: &str) -> u64 {
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    text.hash(&mut hasher);
    hasher.finish()
}

/// A store that interns strings into [`Atom`]s.
///
/// Interning the same string twice through one store returns atoms that share
/// the same backing allocation. Each store owns an independent set of
/// allocations, so two different stores never share an allocation.
#[derive(Default)]
pub struct AtomStore {
    // Keyed by hash, with a bucket per hash to disambiguate collisions by
    // comparing the actual string content.
    data: HashMap<u64, Vec<Atom>>,
}

impl AtomStore {
    /// Interns `text`, returning an [`Atom`] for it.
    ///
    /// If the same content was interned before through this store, the existing
    /// atom (sharing its allocation) is returned.
    pub fn atom<'a>(&mut self, text: impl Into<Cow<'a, str>>) -> Atom {
        let text = text.into();
        let hash = hash_str(&text);

        let bucket = self.data.entry(hash).or_default();

        for existing in bucket.iter() {
            if existing.as_str() == text {
                return existing.clone();
            }
        }

        let atom = Atom::new(text.into_owned().into_boxed_str(), hash);
        bucket.push(atom.clone());
        atom
    }
}

