[metadata] {"type": "create", "filePath": "/workspace/repo/crates/hstr/src/tests.rs", "content": "use crate::{Atom, AtomStore};

#[test]
fn same_store_same_content_shares_unsafe_data() {
    let mut store = AtomStore::default();

    let a = store.atom("hello");
    let b = store.atom("hello");

    assert!(a.unsafe_data == b.unsafe_data);
    assert_eq!(a, b);
}

#[test]
fn same_store_different_content_differs() {
    let mut store = AtomStore::default();

    let a = store.atom("hello");
    let b = store.atom("world");

    assert!(a.unsafe_data != b.unsafe_data);
    assert_ne!(a, b);
}

#[test]
fn different_stores_same_content_differ_in_unsafe_data() {
    let mut store1 = AtomStore::default();
    let mut store2 = AtomStore::default();

    let a = store1.atom("hello");
    let b = store2.atom("hello");

    // Distinct backing allocations => distinct `unsafe_data`.
    assert!(a.unsafe_data != b.unsafe_data);
}

#[test]
fn different_stores_same_content_compare_equal() {
    let mut store1 = AtomStore::default();
    let mut store2 = AtomStore::default();

    let a = store1.atom("hello");
    let b = store2.atom("hello");

    assert_eq!(a, b);
}

#[test]
fn hash_is_consistent_across_stores() {
    let mut store1 = AtomStore::default();
    let mut store2 = AtomStore::default();

    let a = store1.atom("hello");
    let b = store2.atom("hello");

    assert_eq!(a.get_hash(), b.get_hash());
}

#[test]
fn atom_outlives_its_store() {
    let atom: Atom = {
        let mut store = AtomStore::default();
        store.atom("persistent")
    };

    // The store is gone, but the atom is still usable.
    let cloned = atom.clone();
    assert_eq!(atom, cloned);
    assert_eq!(&*atom, "persistent");
}

#[test]
fn accepts_owned_and_borrowed() {
    let mut store = AtomStore::default();

    let from_borrowed = store.atom("shared");
    let from_owned = store.atom(String::from("shared"));

    assert!(from_borrowed.unsafe_data == from_owned.unsafe_data);
    assert_eq!(from_borrowed, from_owned);
}
